59	    /** Add a claim for a person, naming the number of the claim it corrects (only a correction keeps it). */
60	    @Transactional
61	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
62	            String corrects) {
63	        LocalDate on = date != null ? date : sheets.today(sheetId);
