79	    /** Change a draft claim's amount, date and note; a date left out takes the sheet's today. Refused
80	     *  when the claim is not a draft (an open claim is changed by voiding it and adding a new one), and
81	     *  when the claim's date, or the new one, falls inside a closed period, and when the new one is
82	     *  after the person's retirement day. */
83	    @Transactional
84	    public Claim edit(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note,
85	            String corrects) {
86	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
87	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
88	        if (claim.getStatus() != ClaimStatus.DRAFT) {
89	            throw new ResponseStatusException(HttpStatus.CONFLICT,
90	                    "A " + claim.getStatus() + " claim cannot be edited");
91	        }
92	        LocalDate on = date != null ? date : sheets.today(sheetId);
93	        refuseClosed(sheetId, claim.getDate());
94	        refuseClosed(sheetId, on);
95	        refuseRetired(person(sheetId, claim.getPersonId()), on);
96	        Claim corrected = corrected(sheetId, claim.getPersonId(), amount, corrects);
97	        return rollup.tracking(sheetId, user, () -> {
98	            claim.setAmount(amount);
99	            claim.setCorrects(corrected == null ? null : corrected.getNumber());
100	            claim.setCorrectedDate(corrected == null ? null : corrected.getDate());
101	            claim.setDate(on);
102	            claim.setNote(note);
103	            Claim saved = claims.saveAndFlush(claim);
