109	    /** Move a claim to a new status; a change its current status does not allow is refused, and so
110	     *  is settling a claim by the user who opened it, and any change to a claim dated inside a closed
111	     *  period. A clerk settling a claim whose due is above the sheet's clerk limit leaves it pending
112	     *  a steward's approval instead. */
113	    @Transactional
114	    public Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus to) {
115	        Claim claim = lock(sheetId, claimId);
116	        refuseClosed(sheetId, claim.getDate());
117	        if (!claim.getStatus().canBecome(to) || to == ClaimStatus.PENDING) {
118	            throw new ResponseStatusException(HttpStatus.CONFLICT,
119	                    "A " + claim.getStatus() + " claim cannot become " + to);
120	        }
121	        if (to == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
122	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
123	                    "The user who opened a claim cannot settle it");
124	        }
125	        ClaimStatus becomes = to == ClaimStatus.SETTLED && overClerkLimit(sheetId, user, claim)
126	                ? ClaimStatus.PENDING : to;
127	        return rollup.tracking(sheetId, user, () -> {
128	            Person person = person(sheetId, claim.getPersonId());
129	            if (becomes == ClaimStatus.SETTLED) {
130	                // Settling fixes the due at what it is now, while the claim is still open (the figure a
131	                // statement bound it to, if any, and its late charge); later changes to rates, the
132	                // late percent and the sheet's today do not alter it.
133	                claim.setSettledDue(dues.figure(sheetId, person, claim));
134	            }
135	            // A void claim keeps the number it had (never reused).
136	            claim.setStatus(becomes);
137	            if (becomes == ClaimStatus.OPEN) {
138	                claim.setNumber(nextNumber(sheetId, claim.getDate()));
139	                claim.setOpenedBy(user);
140	            }
141	            logStatus(sheetId, user, person, claim);
142	            Claim saved = claims.saveAndFlush(claim);
143	            String event = switch (becomes) {
144	                case OPEN -> "CLAIM_OPENED";
145	                case PENDING -> "CLAIM_PENDING";
146	                case SETTLED -> "CLAIM_SETTLED";
147	                case VOID -> "CLAIM_VOIDED";
148	                case DRAFT -> throw new IllegalStateException("a claim never returns to DRAFT");
149	            };
150	            String line = record(event, sheetId, user, person, saved);
151	            if (becomes == ClaimStatus.SETTLED) {
152	                line += " due=" + dueText(saved.getSettledDue());
153	            }
154	            audit.recordOnCommit(line);
155	            return saved;
156	        });
157	    }
158	
159	    /** Approve a pending claim: it becomes settled, its due fixed at the figure it has now (its live
160	     *  figure and late charge). Refused unless the claim is pending, the user is a steward and is not
161	     *  the one who opened it, and the claim's period is open. */
162	    @Transactional
163	    public Claim approve(String sheetId, String user, long claimId) {
164	        Claim claim = lockPending(sheetId, user, claimId);
165	        if (user.equals(claim.getOpenedBy())) {
166	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
167	                    "The user who opened a claim cannot approve it");
168	        }
169	        return rollup.tracking(sheetId, user, () -> {
170	            Person person = person(sheetId, claim.getPersonId());
171	            claim.setSettledDue(dues.figure(sheetId, person, claim));
172	            claim.setStatus(ClaimStatus.SETTLED);
173	            logStatus(sheetId, user, person, claim);
174	            Claim saved = claims.saveAndFlush(claim);
175	            audit.recordOnCommit(record("CLAIM_APPROVED", sheetId, user, person, saved)
176	                    + " due=" + dueText(saved.getSettledDue()));
177	            return saved;
178	        });
179	    }
180	
181	    /** Reject a pending claim for a reason: it is open again, bound again by its person's last
182	     *  statement if that statement included it. Refused unless the claim is pending, the user is a
183	     *  steward, and the claim's period is open. */
184	    @Transactional
185	    public Claim reject(String sheetId, String user, long claimId, String reason) {
186	        Claim claim = lockPending(sheetId, user, claimId);
187	        return rollup.tracking(sheetId, user, () -> {
188	            Person person = person(sheetId, claim.getPersonId());
189	            claim.setStatus(ClaimStatus.OPEN);
190	            logStatus(sheetId, user, person, claim);
191	            Claim saved = claims.saveAndFlush(claim);
192	            audit.recordOnCommit(record("CLAIM_REJECTED", sheetId, user, person, saved) + " reason=" + reason);
193	            return saved;
194	        });
195	    }
