197	    /** Move a draft, open or pending claim to another person on the sheet. It keeps its number, date
198	     *  and status, loses any figure a statement bound it to, and is listed as its new person's newest
199	     *  claim. Refused unless the user is a steward, and when the claim is settled or void, the person
200	     *  is the one it is already for, the claim's period is closed, or the claim is dated after the
201	     *  new person's retirement day. */
202	    @Transactional
203	    public Claim reassign(String sheetId, String user, long claimId, long toPersonId) {
204	        Claim claim = lock(sheetId, claimId);
205	        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
206	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can reassign a claim");
207	        }
208	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
209	            throw new ResponseStatusException(HttpStatus.CONFLICT,
210	                    "A " + claim.getStatus() + " claim cannot be reassigned");
211	        }
212	        if (claim.getPersonId() == toPersonId) {
213	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The claim is already that person's");
214	        }
215	        refuseClosed(sheetId, claim.getDate());
216	        Person from = person(sheetId, claim.getPersonId());
217	        Person to = person(sheetId, toPersonId);
218	        refuseRetired(to, claim.getDate());
219	        return rollup.tracking(sheetId, user, () -> {
220	            claim.moveTo(to.getId(), claims.nextListed());
221	            Claim saved = claims.saveAndFlush(claim);
222	            audit.recordOnCommit(record("CLAIM_REASSIGNED", sheetId, user, to, saved)
223	                    + " from=" + from.getName() + " to=" + to.getName());
224	            return saved;
225	        });
226	    }
