228	    /** The pending claim a steward approves or rejects, locked; refused when it is not pending, the
229	     *  user is not a steward, or its period is closed. */
230	    private Claim lockPending(String sheetId, String user, long claimId) {
231	        Claim claim = lock(sheetId, claimId);
232	        refuseClosed(sheetId, claim.getDate());
233	        if (claim.getStatus() != ClaimStatus.PENDING) {
234	            throw new ResponseStatusException(HttpStatus.CONFLICT,
235	                    "Only a PENDING claim can be approved or rejected");
236	        }
237	        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
238	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
239	                    "Only a steward can approve or reject a claim");
240	        }
241	        return claim;
242	    }
243	
244	    /** Log the status the claim has now, changed by the user on the sheet's today, with its due as
245	     *  computed at this moment. */
246	    private void logStatus(String sheetId, String user, Person person, Claim claim) {
247	        claim.logStatus(user, sheets.today(sheetId), dues.figure(sheetId, person, claim));
248	    }
249	
250	    private Claim lock(String sheetId, long claimId) {
251	        return claims.lockByIdAndSheetId(claimId, sheetId)
252	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
253	    }
254	
255	    private static String dueText(BigDecimal due) {
256	        return due == null ? "n/a" : due.setScale(2).toPlainString();
257	    }
258	
259	    /** The number for a claim of the date opened now: under period numbering, the next in its period
260	     *  (<period name>-<n>), or for one in no period the next X-<n>; otherwise the next on the sheet. */
261	    private String nextNumber(String sheetId, LocalDate date) {
262	        if (!sheets.periodNumbering(sheetId)) {
263	            return String.valueOf(sheets.nextClaimNumber(sheetId));
264	        }
265	        return periods.findOn(sheetId, date)
266	                .map(p -> {
267	                    periods.advanceClaimNumber(p.getId());
268	                    return p.getName() + "-" + periods.lastClaimNumber(p.getId());
269	                })
270	                .orElseGet(() -> "X-" + sheets.nextUnperiodNumber(sheetId));
271	    }
272	
273	    /** The claim a claim of the amount corrects: none for an amount of 0.00 or more; for a correction
274	     *  (a negative amount), the one of the number given, which must be a settled claim of the person,
275	     *  or else it is refused. */
276	    private Claim corrected(String sheetId, long personId, BigDecimal amount, String corrects) {
277	        if (amount.signum() >= 0) {
278	            return null;
279	        }
280	        return (corrects == null ? Optional.<Claim>empty()
281	                : claims.findBySheetIdAndPersonIdAndNumberAndStatus(sheetId, personId, corrects, ClaimStatus.SETTLED))
282	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.BAD_REQUEST,
283	                        "A negative amount must correct a settled claim of the same person"));
284	    }
285	
286	    /** Refuse a change to a claim dated on the day when the day falls inside a closed period. */
287	    private void refuseClosed(String sheetId, LocalDate day) {
288	        if (periods.closedOn(sheetId, day)) {
289	            throw new ResponseStatusException(HttpStatus.LOCKED, "That claim's period is closed");
290	        }
291	    }
292	
293	    /** Whether a clerk is settling a claim whose due is above the sheet's clerk limit; a claim with
294	     *  no due (n/a) is within any limit, and a steward settles anything. */
295	    private boolean overClerkLimit(String sheetId, String user, Claim claim) {
296	        BigDecimal limit = sheets.clerkLimit(sheetId);
297	        if (limit == null || SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
298	            return false;
299	        }
300	        BigDecimal due = dues.figure(sheetId, person(sheetId, claim.getPersonId()), claim);
301	        return due != null && due.compareTo(limit) > 0;
302	    }
303	
304	    /** Refuse a claim of the person dated after the day they are retired from. */
305	    private static void refuseRetired(Person person, LocalDate day) {
306	        if (person.getRetiredFrom() != null && day.isAfter(person.getRetiredFrom())) {
307	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
308	                    "A claim cannot be dated after the person's retirement");
309	        }
310	    }
311	
312	    private Person person(String sheetId, long personId) {
313	        return people.findByIdAndSheetId(personId, sheetId)
314	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
315	    }
316	
317	    /** An audit record about a claim; one that has a number carries it at the end. */
318	    private static String record(String event, String sheetId, String user, Person person, Claim claim) {
319	        String number = claim.getNumber();
320	        return event + " sheet=" + sheetId + " by=" + user + " person=" + person.getName()
321	                + " amount=" + claim.getAmount().setScale(2).toPlainString() + " date=" + claim.getDate()
322	                + (number != null ? " number=" + number : "");
323	    }
324	}
